$ErrorActionPreference='Stop'
$Base='http://localhost:5004'
$records=[Collections.Generic.List[object]]::new()
function Send-Frame($Socket,[string]$Text){$bytes=[Text.Encoding]::UTF8.GetBytes($Text);$Socket.SendAsync([ArraySegment[byte]]::new($bytes),[Net.WebSockets.WebSocketMessageType]::Text,$true,[Threading.CancellationToken]::None).GetAwaiter().GetResult()|Out-Null}
function Receive-Frame($Socket){$buffer=New-Object byte[] 65536;$builder=[Text.StringBuilder]::new();do{$result=$Socket.ReceiveAsync([ArraySegment[byte]]::new($buffer),[Threading.CancellationToken]::None).GetAwaiter().GetResult();[void]$builder.Append([Text.Encoding]::UTF8.GetString($buffer,0,$result.Count))}while(!$result.EndOfMessage);$builder.ToString()}
function Invoke-Chat([string]$Session,[string]$Query){$neg=Invoke-RestMethod -Method Post -Uri "$Base/hubs/chat/negotiate?negotiateVersion=1";$ws=[Net.WebSockets.ClientWebSocket]::new();try{$uri=[Uri]("ws://localhost:5004/hubs/chat?id="+[Uri]::EscapeDataString($neg.connectionToken));$ws.ConnectAsync($uri,[Threading.CancellationToken]::None).GetAwaiter().GetResult();Send-Frame $ws ('{"protocol":"json","version":1}'+[char]30);$null=Receive-Frame $ws;$payload=@{type=1;target='SendMessage';arguments=@($Session,$Query)}|ConvertTo-Json -Compress;$sw=[Diagnostics.Stopwatch]::StartNew();Send-Frame $ws ($payload+[char]30);do{$raw=Receive-Frame $ws;$events=$raw.Split([char]30,[StringSplitOptions]::RemoveEmptyEntries)|ForEach-Object{$_|ConvertFrom-Json};$event=$events|Where-Object{$_.target -eq 'ReceiveChatResponse'}|Select-Object -First 1}while($null -eq $event);$sw.Stop();[pscustomobject]@{Response=$event.arguments[0];Latency=[math]::Round($sw.Elapsed.TotalSeconds,4)}}finally{$ws.Dispose()}}
function Add-Test([string]$Phase,[string]$Case,[string]$Session,[string]$Query,[string]$Asset,[string]$Period,[string]$ExpectedAction){try{$result=Invoke-Chat $Session $Query;$r=$result.Response;$p=$r.extractedParameters;$pass=$true;if($Asset){$pass=$pass-and($p.assetName-eq$Asset)};if($Period){$pass=$pass-and($p.timeRange-eq$Period)};if($ExpectedAction){$pass=$pass-and($r.suggestedAction-eq$ExpectedAction)};$records.Add([pscustomobject]@{timestampIst=(Get-Date).ToString('yyyy-MM-ddTHH:mm:ss.fffzzz');phase=$Phase;caseId=$Case;query=$Query;expectedAsset=$Asset;expectedPeriod=$Period;expectedAction=$ExpectedAction;passed=$pass;latencySeconds=$result.Latency;decisionModel=$r.decisionModel;inputTokens=$r.inputTokens;outputTokens=$r.outputTokens;totalTokens=$r.totalTokens;reply=$r.replyMessage;suggestedAction=$r.suggestedAction;parameters=$p;jobId=$r.jobId;error=$null})}catch{$records.Add([pscustomobject]@{timestampIst=(Get-Date).ToString('yyyy-MM-ddTHH:mm:ss.fffzzz');phase=$Phase;caseId=$Case;query=$Query;expectedAsset=$Asset;expectedPeriod=$Period;expectedAction=$ExpectedAction;passed=$false;latencySeconds=$null;decisionModel=$null;inputTokens=$null;outputTokens=$null;totalTokens=$null;reply=$null;suggestedAction=$null;parameters=$null;jobId=$null;error=$_.Exception.Message})}}
function Snapshot([string]$Label){$lines=docker stats --no-stream --format '{{json .}}' sensorbot5_backend sensorbot5_jev sensorbot5_ollama sensorbot5_timescaledb sensorbot5_rabbitmq sensorbot5_frontend;$items=@($lines|ForEach-Object{$_|ConvertFrom-Json});[pscustomobject]@{label=$Label;timestampIst=(Get-Date).ToString('yyyy-MM-ddTHH:mm:ss.fffzzz');containers=$items}}
$started=(Get-Date).ToString('yyyy-MM-ddTHH:mm:ss.fffzzz');$snapshots=[Collections.Generic.List[object]]::new();$snapshots.Add((Snapshot 'baseline'))
$s='state-air-'+[guid]::NewGuid();Add-Test 'stateful' 'air-1' $s 'air compresr motr' 'Air Compressor Motor' '' 'select_timeframe';Add-Test 'stateful' 'air-2' $s 'lst five dys' 'Air Compressor Motor' '5d' 'confirm_queue';Add-Test 'stateful' 'air-3' $s 'make that weekli instead' 'Air Compressor Motor' '7d' 'confirm_queue';Add-Test 'stateful' 'air-4' $s 'yes generate it' 'Air Compressor Motor' '7d' 'confirm_queue'
$s='state-switch-'+[guid]::NewGuid();Add-Test 'stateful' 'switch-1' $s 'boilr feed pum report' 'Boiler Feed Pump Motor' '' 'select_timeframe';Add-Test 'stateful' 'switch-2' $s 'past too weks' 'Boiler Feed Pump Motor' '14d' 'confirm_queue';Add-Test 'stateful' 'switch-3' $s 'no chnge machin to coling towr fan' 'Cooling Tower Fan Motor' '14d' 'confirm_queue';Add-Test 'stateful' 'switch-4' $s 'clear this' '' '' 'select_asset'
$cases=@(
@('catalog','what machins can i get reprts for','','','select_asset'),
@('air-oneshot','air compresr telemetry pdf last five days','Air Compressor Motor','5d','confirm_queue'),
@('boiler-oneshot','bfp motr for a fortnight','Boiler Feed Pump Motor','14d','confirm_queue'),
@('cooling-oneshot','coling towr fan daily helth repot','Cooling Tower Fan Motor','24h','confirm_queue'),
@('conveyor-oneshot','main convayr motr monthli report','Main Conveyor Drive Motor','30d','confirm_queue'),
@('crusher-arbitrary','primary crusher report for last 3 days','Primary Crusher Motor','3d','confirm_queue'),
@('offtopic','tell me the weather in mumbai','','','none'))
foreach($c in $cases){Add-Test 'single' $c[0] ('single-'+[guid]::NewGuid()) $c[1] $c[2] $c[3] $c[4]}
$snapshots.Add((Snapshot 'after-functional'))
$loadAssets=@('Air Compressor Motor','Boiler Feed Pump Motor','Cooling Tower Fan Motor','Main Conveyor Drive Motor','Primary Crusher Motor');$loadPeriods=@('24h','5d','7d','14d','30d');for($i=0;$i-lt 10;$i++){Add-Test 'repeated-load' ("load-$($i+1)") ('load-'+[guid]::NewGuid()) ("make a $($loadPeriods[$i%5]) telemetry report for $($loadAssets[$i%5])") $loadAssets[$i%5] $loadPeriods[$i%5] 'confirm_queue'}
$snapshots.Add((Snapshot 'after-repeated-load'));$completed=(Get-Date).ToString('yyyy-MM-ddTHH:mm:ss.fffzzz');$bundle=[pscustomobject]@{startedAtIst=$started;completedAtIst=$completed;records=$records;resourceSnapshots=$snapshots};$bundle|ConvertTo-Json -Depth 12|Set-Content -LiteralPath (Join-Path $PSScriptRoot 'raw_results.json') -Encoding utf8;Write-Output "Completed $($records.Count) turns; passed $(($records|Where-Object passed).Count)."
